create table if not exists public.agent_engines (agent_id text primary key references public.agent_profiles(id) on delete cascade, runtime_version integer not null default 1, memory_limit_mb integer not null default 100 check(memory_limit_mb between 16 and 100), context_limit_chars integer not null default 12000, model text not null default 'openai/gpt-oss-20b', enabled boolean not null default true, config jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
insert into public.agent_engines(agent_id) select id from public.agent_profiles on conflict(agent_id) do nothing;
create table if not exists public.agent_memory (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete cascade, agent_id text not null references public.agent_profiles(id), memory_type text not null check(memory_type in ('short_term','long_term','summary')), content text not null, importance smallint not null default 1 check(importance between 1 and 5), token_estimate integer not null default 0, created_at timestamptz not null default now(), expires_at timestamptz);
create index if not exists agent_memory_lookup_idx on public.agent_memory(user_id,subject_id,agent_id,created_at desc);
alter table public.agent_engines enable row level security; alter table public.agent_memory enable row level security;
drop policy if exists agent_engines_read on public.agent_engines; create policy agent_engines_read on public.agent_engines for select using(enabled=true);
drop policy if exists agent_memory_owner on public.agent_memory; create policy agent_memory_owner on public.agent_memory for all using(user_id=auth.uid()) with check(user_id=auth.uid());
